#!/usr/bin/env node
// SEO enforcement. Exits 1 if a page ships without the metadata it must carry,
// (sitemap drift is bin/check-sitemaps.mjs's job — see the note below).
//
// This exists for the same reason bin/check-images.mjs and bin/check-forms.mjs
// do. A page that loses its canonical, its description or its share image does
// not look broken — it looks exactly right, in the browser and in the pixel
// diff, and the damage shows up weeks later in somebody else's search console.
// The whole point of moving off Yoast is that the metadata is now generated by
// code; code that generates metadata needs something that reads it back.
//
// Two of the checks are specifically regression guards for the port:
//
//   * DUPLICATE OG. The live WordPress site emits two competing sets of Open
//     Graph tags on every page (Nicepage's, then Yoast's) and consumers take
//     the first, which is the wrong one. src/seo.config.ts de-duplicates them.
//     If that ever stops running, the pages still render and the wrong card
//     comes back — silently. This fails the build instead.
//
// The sitemaps are no longer this file's concern. They were Yoast's own files,
// copied at gate 8, when three assertions here guarded them against drift; they
// are generated from the built site now and bin/check-sitemaps.mjs owns checking
// them, including the cases a generator makes possible that a copy never did.
//
// It runs inside `npm run build`, joined with &&, so it runs in Workers Builds
// on every deploy and a violation fails the deploy rather than reaching anyone.
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist', 'client');
const SITE = 'https://www.rexdalemobilewash.ca';

/** Properties Open Graph allows only one of. A second one is a bug, not a list. */
const SINGLE_OG = ['og:title', 'og:description', 'og:url', 'og:type', 'og:site_name', 'og:locale'];

/** Longer than this and Google truncates the snippet in the results page. */
const DESC_MAX = 160;

const walk = (d) => readdirSync(d).flatMap((n) => {
  const p = join(d, n);
  return statSync(p).isDirectory() ? walk(p) : (n.endsWith('.html') ? [p] : []);
});

const attr = (tag, name) => {
  const m = tag.match(new RegExp(`${name}\\s*=\\s*["']([^"']*)["']`, 'i'));
  return m ? m[1] : null;
};
const metas = (html, kind) =>
  (html.match(/<meta\b[^>]*>/gi) || [])
    .map((t) => [attr(t, kind), attr(t, 'content')])
    .filter(([k]) => k !== null);

const decode = (s) => s
  .replace(/&(?:quot|#0*34);/gi, '"').replace(/&(?:apos|#0*39);/gi, "'")
  .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&amp;/gi, '&');

const fails = [];
const warns = [];
const pages = [];

for (const file of walk(dist)) {
  const html = readFileSync(file, 'utf8');
  const route = '/' + file.slice(dist.length + 1).replace(/index\.html$/, '');
  const head = html.slice(0, html.indexOf('</head>') + 1);
  const fail = (m) => fails.push([route, m]);
  const warn = (m) => warns.push([route, m]);

  const titles = head.match(/<title>([\s\S]*?)<\/title>/gi) || [];
  const props = metas(head, 'property');
  const names = metas(head, 'name');
  const canon = (head.match(/<link\b[^>]*rel=["']canonical["'][^>]*>/gi) || [])
    .map((t) => attr(t, 'href'));
  const robots = (names.find(([n]) => n.toLowerCase() === 'robots') || [])[1] || '';
  const noindex = /noindex/i.test(robots);
  const description = (names.find(([n]) => n.toLowerCase() === 'description') || [])[1];

  pages.push({ route, canonical: canon[0], noindex, description });

  // --- title -------------------------------------------------------------
  if (titles.length !== 1) fail(`${titles.length} <title> tags`);
  else if (!titles[0].replace(/<\/?title>/gi, '').trim()) fail('empty <title>');

  // --- description -------------------------------------------------------
  // A noindex page is not competing for a snippet, so a missing description
  // there is untidy rather than broken.
  if (!description) (noindex ? warn : fail)('no meta description');
  else if (decode(description).length > DESC_MAX)
    warn(`description is ${decode(description).length} chars (>${DESC_MAX}, will be truncated)`);

  // --- canonical ---------------------------------------------------------
  // The 404 is the one page with nothing to be canonical to: it is served for
  // every unknown URL, so any href it named would be a lie about a different page.
  if (route === '/404.html') {
    if (!noindex) fail('the 404 page is not noindex');
  } else if (canon.length !== 1) {
    fail(`${canon.length} canonical links`);
  } else if (!canon[0].startsWith(SITE)) {
    fail(`canonical points off-site: ${canon[0]}`);
  }

  // --- open graph --------------------------------------------------------
  for (const p of SINGLE_OG) {
    const n = props.filter(([k]) => k.toLowerCase() === p).length;
    if (n > 1) fail(`${n}x ${p} — de-duplication did not run`);
  }
  const image = props.filter(([k]) => k.toLowerCase() === 'og:image');
  if (image.length === 0) (noindex ? warn : fail)('no og:image');
  else if (image.length === 1) {
    for (const dim of ['og:image:width', 'og:image:height', 'og:image:alt'])
      if (!props.some(([k]) => k.toLowerCase() === dim)) warn(`og:image without ${dim}`);
  }

  // --- structured data ---------------------------------------------------
  const blocks = head.match(
    /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
  for (const b of blocks) {
    const body = b.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, '');
    let doc;
    try {
      doc = JSON.parse(body);
    } catch (e) {
      fail(`JSON-LD does not parse: ${e.message}`);
      continue;
    }
    const graph = Array.isArray(doc['@graph']) ? doc['@graph'] : [doc];
    const types = (n) => [].concat(n['@type'] ?? []);
    const org = graph.find((n) => types(n).includes('Organization'));
    if (org) {
      // The enrichment in src/seo.config.ts. Its absence means the ported graph
      // shipped raw: a 60-year-old local trade business with no machine-readable
      // address, which is the single thing this site's structured data most needs.
      if (!types(org).includes('ProfessionalService'))
        fail('Organization is not typed as a LocalBusiness');
      for (const k of ['address', 'telephone', 'areaServed'])
        if (!org[k]) fail(`Organization has no ${k}`);
    }
  }
}

// --- sitemaps -------------------------------------------------------------
// Owned by bin/check-seo.mjs no longer. Three assertions used to live here —
// robots.txt names a Sitemap:, every <loc> resolves to a page this site builds,
// and no noindex page sits in a sitemap — written when the sitemaps were still
// Yoast's own files copied out of the capture. They are generated now
// (tools/gen_sitemaps.py), and bin/check-sitemaps.mjs checks all three plus the
// cases only a generator makes possible: a served page in no sitemap at all, an
// empty sitemap, a stale or missing lastmod, an image off the image host.
//
// Both checks run in `npm run build`. Two of them reading the same files is two
// of them drifting, so this one stops at the <head>.

// --- duplicate descriptions ----------------------------------------------
// Two pages sharing a description compete for the same snippet and tell Google
// they are the same page. This is how /water-tanker-service/ shipped live
// carrying /de-icing-service/'s description word for word.
const byDesc = new Map();
for (const p of pages) {
  if (!p.description) continue;
  const k = decode(p.description).trim().toLowerCase();
  byDesc.set(k, [...(byDesc.get(k) || []), p.route]);
}
for (const [, routes] of byDesc)
  if (routes.length > 1) fails.push([routes[0], `shares its description with ${routes.slice(1).join(', ')}`]);

// --- report ---------------------------------------------------------------
const p = (l, n) => console.log(`  ${(l + ' ').padEnd(36, '.')} ${n}`);
console.log('\nSEO CHECK\n');
p('pages checked', pages.length);
p('indexable', pages.filter((x) => !x.noindex).length);
p('warnings', warns.length);
p('failures', fails.length);

if (warns.length) {
  console.log('\n  warnings');
  for (const [route, m] of warns) console.log(`    ${route.padEnd(30)} ${m}`);
}
if (fails.length) {
  console.log('\n  FAILURES');
  for (const [route, m] of fails) console.log(`    ${route.padEnd(30)} ${m}`);
  console.log('\nSEO CHECK FAILED\n');
  process.exit(1);
}
console.log('\nSEO CHECK PASSED\n');
